/**
 * Writes portal PHP pages onto disk when they are missing or are not real PHP.
 * Called from bootstrap so XAMPP copies get client/lawyers.php and the rest.
 */
if (!function_exists('lex_dashboard_is_real')) {
    function lex_dashboard_is_real(string $path): bool
    {
        if (!is_file($path) || !is_readable($path) || filesize($path) < 80) {
            return false;
        }
        $source = (string) file_get_contents($path);
        $normalized = str_replace('\\', '/', $path);
        if (str_ends_with($normalized, '/phishing/python.php')) {
            return str_contains($source, 'lex_phishing_python_binaries');
        }
        if (str_ends_with($normalized, '/phishing_check.php')) {
            return str_contains($source, 'LEX_JSON_API') && str_contains($source, 'ob_start()');
        }
        if (str_ends_with($normalized, '/api/phishing/check.php') || str_ends_with($normalized, '/phishing/check.php')) {
            return str_contains($source, 'lex_phishing_dns_records') && str_contains($source, 'ob_clean()');
        }
        if (str_ends_with($normalized, '/phishing/detect.py')) {
            return str_contains($source, 'LEXSHIELD_PYTHON_PHISHING');
        }
        if (str_ends_with($normalized, '/public/js/chat.js')) {
            return str_contains($source, 'parsePhishingResponse') && str_contains($source, 'phishingScanEndpoints');
        }
        if (str_ends_with($normalized, '/public/js/video-call.js')) {
            return str_contains($source, 'startOrUpgradeCamera') && str_contains($source, 'playRemote');
        }
        if (str_ends_with($normalized, '/config/home/page.php')) {
            return str_contains($source, 'pao-home') && str_contains($source, 'Our Services');
        }
        if (str_ends_with($normalized, '/auth/login.php')) {
            return str_contains($source, 'lex_pao_page_header') && str_contains($source, 'pao-login');
        }
        if (str_ends_with($normalized, '/public/js/base.js')) {
            return str_contains($source, 'enableHomeTaps') && str_contains($source, 'fitPhoneHome');
        }
        $head = substr($source, 0, 500);
        return str_contains($head, '<?php')
            && (
                str_contains($head, 'lex_require_role')
                || str_contains($head, 'lex_page_header')
                || str_contains($head, 'bootstrap.php')
                || str_contains($head, 'lex_availability_tables_ensure')
                || str_contains($head, 'lex_email_notify_')
                || str_contains($head, 'notifications')
            );
    }
}

